package cn.huankan.collector;

import cn.huankan.evidence.EvidenceService;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

/** Explicit, bounded diagnostic requests. No alternate proxies, redirects or retry loops. */
@Service public class OfficialResourceService {
 private final JdbcTemplate db;private final ObjectMapper json;private final CollectorGuard guard;private final BlsCollector bls;private final TransactionTemplate tx;
 public OfficialResourceService(JdbcTemplate d,ObjectMapper j,CollectorGuard g,BlsCollector b,org.springframework.transaction.PlatformTransactionManager m){db=d;json=j;guard=g;bls=b;tx=new TransactionTemplate(m);}
 public String encode(Object v){try{return json.writeValueAsString(v);}catch(Exception e){throw new IllegalArgumentException("诊断记录不能编码",e);}}
 public Object status(){return Map.of("policies",db.queryForList("SELECT * FROM official_resource_policy ORDER BY purpose,url"),"requests",db.queryForList("SELECT id,url,method,requested_at,received_at,http_status,headers,sha256,network,error,octet_length(raw_content) response_bytes FROM official_resource_response ORDER BY requested_at DESC LIMIT 30"),"state","403只能确认访问被拒绝；根因须结合响应和网络证据，不规避限制");}
 public Map<String,Object> request(String url,String method){
  var p=db.queryForMap("SELECT * FROM official_resource_policy WHERE url=?",url);
  if(!Boolean.TRUE.equals(p.get("access_allowed"))||!Boolean.TRUE.equals(p.get("storage_allowed"))||p.get("reviewed_at")==null)throw new IllegalStateException("资源使用范围尚未核验");
  if(!method.equals("GET")&&!method.equals("POST")||method.equals("POST")&&!url.equals(BlsSourceAdapter.URL))throw new IllegalArgumentException("请求方法与官方路径不匹配");
  UUID id=UUID.randomUUID();Instant started=Instant.now();
  // The reservation persists before sending. A second instance cannot race the explicit daily allowance.
  tx.executeWithoutResult(s->{db.execute("SELECT pg_advisory_xact_lock(742047)");if(db.queryForObject("SELECT count(*) FROM official_resource_response WHERE url=? AND requested_at>now()-interval '24 hours'",Long.class,url)>=1)throw new IllegalStateException("此资源24小时内已经诊断，停止重复请求");db.update("INSERT INTO official_resource_response(id,url,method,requested_at,request_info,headers,network,error) VALUES(?,?,?,?, '{}'::jsonb,'{}'::jsonb,'{}'::jsonb,'REQUEST_RESERVED')",id,url,method,java.sql.Timestamp.from(started));});
  // Immutable reservation is retained. Final response is a separate append-only record using the same trace key.
  UUID resultId=UUID.randomUUID(),job=null,request=null;Integer status=null;byte[] bytes=null;String error=null;var network=new LinkedHashMap<String,Object>();var headers=new LinkedHashMap<String,Object>();
  String body=method.equals("POST")?"{\"seriesid\":[\"CUUR0000SA0\"],\"startyear\":\"2025\",\"endyear\":\"2026\"}":"";
  var info=Map.of("trace_id",id,"method",method,"url",url,"body",body,"content_type",method.equals("POST")?"application/json":"未发送","accept",url.contains("api.bls.gov")?"application/json":"text/plain,text/html;q=0.9","user_agent","HUANKAN/0.1 official-data-research","timeout_seconds",30,"redirects","禁止","size_limit",p.get("max_bytes"));
  try{
   URI uri=URI.create(url);network.put("dns",Arrays.stream(InetAddress.getAllByName(uri.getHost())).map(InetAddress::getHostAddress).toList());network.put("proxy",ProxySelector.getDefault()==null?List.of("DIRECT"):ProxySelector.getDefault().select(uri).stream().map(x->x.type().toString()).toList());network.put("environment_proxy_configured",System.getenv("HTTPS_PROXY")!=null||System.getenv("HTTP_PROXY")!=null);
   if(url.contains("api.bls.gov")){job=UUID.randomUUID();db.update("INSERT INTO ingestion_job(id,source_id,status) VALUES(?,'BLS','RUNNING')",job);request=bls.reserve(job,encode(Map.of("diagnostic_method",method,"seriesid",List.of("CUUR0000SA0"))));}
   guard.request(uri.getHost());var builder=HttpRequest.newBuilder(uri).timeout(Duration.ofSeconds(30)).header("User-Agent","HUANKAN/0.1 official-data-research").header("Accept",url.contains("api.bls.gov")?"application/json":"text/plain,text/html;q=0.9");if(method.equals("POST"))builder.header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body));else builder.GET();
   var response=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(10)).followRedirects(HttpClient.Redirect.NEVER).build().send(builder.build(),HttpResponse.BodyHandlers.ofInputStream());status=response.statusCode();
   for(String key:List.of("content-type","content-length","date","last-modified","server","via","retry-after","x-cache"))response.headers().firstValue(key).ifPresent(v->headers.put(key,v));
   response.sslSession().ifPresent(v->{network.put("tls_protocol",v.getProtocol());network.put("tls_cipher",v.getCipherSuite());});
   int limit=status==200?((Number)p.get("max_bytes")).intValue():65536;try(var stream=response.body();var deadline=BodyDeadline.arm(stream,Duration.ofSeconds(30))){bytes=stream.readNBytes(limit+1);deadline.verify();}if(bytes.length>limit){bytes=null;error="SIZE_LIMIT_EXCEEDED";}
   else if(status!=200)error="HTTP_"+status;
  }catch(Exception e){error=CollectorGuard.failure(e);network.put("failure_class",e.getClass().getSimpleName());}
  String apiStatus=null;if(request!=null&&error==null&&bytes!=null){try{apiStatus=json.readTree(bytes).path("status").asText();if(!"REQUEST_SUCCEEDED".equals(apiStatus))error="BLS_API_REJECTED";}catch(Exception e){error="BLS_INVALID_JSON";}}
  if(request!=null){db.update("UPDATE bls_request SET finished_at=clock_timestamp(),http_status=?,raw_response=?,sha256=?,error=?,api_status=? WHERE id=?",status,bytes,bytes==null?null:EvidenceService.hash(bytes),error,apiStatus,request);db.update("UPDATE ingestion_job SET status=?,http_status=?,finished_at=now(),error_code=? WHERE id=?",error==null?"SUCCESS":"FAILED",status,error,job);}
  db.update("INSERT INTO official_resource_response(id,url,method,requested_at,request_info,http_status,headers,raw_content,sha256,network,error) VALUES(?,?,?,?,?::jsonb,?,?::jsonb,?,?,?::jsonb,?)",resultId,url,method,java.sql.Timestamp.from(started),encode(info),status,encode(headers),bytes,bytes==null?null:EvidenceService.hash(bytes),encode(network),error);
  return db.queryForMap("SELECT id,url,http_status,sha256,error,headers,network FROM official_resource_response WHERE id=?",resultId);
 }
 public Object diagnose(){var results=new ArrayList<Object>();for(var p:db.queryForList("SELECT url,purpose FROM official_resource_policy WHERE source_id='BLS' ORDER BY CASE purpose WHEN 'BLS_API' THEN 0 WHEN 'BLS_API_GET' THEN 1 ELSE 2 END,url")){try{results.add(request(p.get("url").toString(),p.get("purpose").equals("BLS_API")?"POST":"GET"));}catch(IllegalStateException e){results.add(Map.of("url",p.get("url"),"message",e.getMessage()));}}return results;}
 public Object syncCalendars(){var result=new ArrayList<Object>();for(var p:db.queryForList("SELECT * FROM official_resource_policy WHERE purpose='CALENDAR' AND access_allowed AND storage_allowed AND display_allowed")){try{var cached=db.queryForList("SELECT id,url,http_status,sha256,error,headers,network FROM official_resource_response WHERE url=? AND http_status=200 AND error IS NULL AND requested_at>now()-interval '24 hours' ORDER BY received_at DESC LIMIT 1",p.get("url"));var response=cached.isEmpty()?request(p.get("url").toString(),"GET"):cached.getFirst();if(Integer.valueOf(200).equals(response.get("http_status"))&&response.get("error")==null){var raw=db.queryForMap("SELECT * FROM official_resource_response WHERE id=?",response.get("id"));String text=new String((byte[])raw.get("raw_content"),StandardCharsets.UTF_8);int saved=0;for(var event:OfficialCalendarParser.parse(p.get("source_id").toString(),text)){String fingerprint=EvidenceService.hash((event.date()+"|"+event.title()+(event.plannedTime()==null?"":"|"+event.plannedTime())).getBytes(StandardCharsets.UTF_8));if(Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM official_release_calendar WHERE source_url=? AND content_hash=?)",Boolean.class,p.get("url"),fingerprint)))continue;int version=db.queryForObject("SELECT COALESCE(max(version),0)+1 FROM official_release_calendar WHERE source_url=? AND planned_date=? AND official_title=?",Integer.class,p.get("url"),java.sql.Date.valueOf(event.date()),event.title());db.update("INSERT INTO official_release_calendar(id,source_id,official_title,title_zh,planned_date,source_timezone,source_url,response_id,excerpt,version,content_hash,planned_time_text) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),p.get("source_id"),event.title(),event.titleZh(),java.sql.Date.valueOf(event.date()),p.get("source_id").equals("ECB")?"Europe/Berlin":"America/New_York",p.get("url"),response.get("id"),event.excerpt(),version,fingerprint,event.plannedTime());saved++;}result.add(Map.of("response",response,"saved",saved));}else result.add(response);}catch(IllegalStateException e){result.add(Map.of("url",p.get("url"),"message",e.getMessage()));}}return result;}
}
